function minimumOperations(nums) {
  let left = 0;
  let right = nums.length - 1;
  let leftSum = nums[left];
  let rightSum = nums[right];
  let operations = 0;

  while (left < right) {
    if (leftSum === rightSum) {
      left++;
      right--;
      leftSum = nums[left];
      rightSum = nums[right];
    } else if (leftSum < rightSum) {
      left++;
      leftSum += nums[left];
      operations++;
    } else {
      right--;
      rightSum += nums[right];
      operations++;
    }
  }
  return operations;
}

