function minimumOperations(nums) {
  // Every final array is a split of nums into consecutive blocks; each merge removes one element.
  const n = nums.length;
  let mostBlocks = 1;
  for (let mask = 0; mask < (1 << (n - 1)); mask++) {
    const blocks = [];
    let total = nums[0];
    for (let i = 1; i < n; i++) {
      if (mask & (1 << (i - 1))) { blocks.push(total); total = nums[i]; }
      else total += nums[i];
    }
    blocks.push(total);
    const mirrored = blocks.every((v, i) => v === blocks[blocks.length - 1 - i]);
    if (mirrored && blocks.length > mostBlocks) mostBlocks = blocks.length;
  }
  return n - mostBlocks;
}

