function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 11);
    const top = rand() < 0.5 ? 3 : 9;
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = 2000;
  if (rand() < 0.5) {
    const top = rand() < 0.5 ? 3 : 1000000;
    return [Array.from({ length: n }, () => int(1, top))];
  }
  // Build mirrored block sums, then cut each block differently on the two sides.
  const split = (sum) => {
    const parts = [];
    while (sum > 0) { const piece = Math.min(sum, int(1, Math.max(1, Math.floor(sum / 2)))); parts.push(piece); sum -= piece; }
    return parts;
  };
  const front = [];
  const back = [];
  while (front.length + back.length < n - 110) {
    const sum = int(1, 50);
    front.push(...split(sum));
    back.unshift(...split(sum));
  }
  return [front.concat(int(1, 1000000), back)];
}
